/* SLICER ownership (G_SLOWN). Legacy exclusive owner is still readable until sl_own_sanitize. */
static void sl_own_sanitize(void)
{
    int32_t v = PKV(6).g[G_SLOWN];
    if (v >= 0 && v <= (int32_t)4) {
        if (v == 0)
            PKV(6).g[G_SLOWN] = (int16_t)((1u << 4) - 1u); /* all SEND */
        else
            PKV(6).g[G_SLOWN] = (int16_t)(((1u << 4) - 1u) ^ (1u << (uint32_t)(v - 1)));
    } else if (v < 0 || v > (int16_t)((1u << 4) - 1u))
        PKV(6).g[G_SLOWN] = (int16_t)((1u << 4) - 1u);
}
static int sl_trk_send(const track_t *t)
{
    int32_t v = PKV(6).g[G_SLOWN];
    uint32_t tr = (uint32_t)(t - PKV(2));
    if (PKV(4)[INS_SLCR])
        return 0;
    if (v >= 0 && v <= (int32_t)4)
        return v == 0; /* legacy: only all-SEND; else CHAIN/USED */
    return (v & (int32_t)(1u << tr)) != 0;
}
static int sl_trk_chain(const track_t *t)
{
    int32_t v = PKV(6).g[G_SLOWN];
    uint32_t tr = (uint32_t)(t - PKV(2));
    if (PKV(4)[INS_SLCR])
        return 0;
    if (v >= 0 && v <= (int32_t)4)
        return v == (int32_t)(tr + 1u);
    return !(v & (int32_t)(1u << tr));
}
static int sl_trk_used(const track_t *t)
{
    int32_t v = PKV(6).g[G_SLOWN];
    if (PKV(4)[INS_SLCR])
        return 1;
    if (v >= 1 && v <= (int32_t)4)
        return v != (int32_t)((t - PKV(2)) + 1u); /* legacy exclusive owner */
    return 0; /* mask form: never USED */
}
