/* 2^(i/192), Q16: pitch ratios in 1/16 semitones, d16 >= -3072 (16 octaves down) */
static uint32_t pow2_q16(int32_t d16)
{
    uint32_t u = (uint32_t)(d16 + 192 * 16), oct = u / 192u; /* no loop for negative d16 */
    uint32_t r = pitch_inc(1600 + u % 192u) / (pitch_inc(1600) >> 16); /* 2^(d/192) via the pitch table */
    return oct >= 16u ? r << (oct - 16u) : r >> (16u - oct);
}
/* ---- user sample slots (loaded from the web editor into flash, see web/EDITOR_PROTOCOL.md)
 * 3 slots of 80 KiB at flash 0xA0000.. (Felucca data region), read through the plain XIP
 * window. Slot = header (magic, count, name, data length, CRC32) + up to 16 zones in the
 * smp_zone_t layout (off relative to the slot's data at +512) + IMA ADPCM data. */
/* SPDX-License-Identifier: GPL-3.0-only
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* FM-1 XIP window: flash offset off (>= 0x4000, the app area start) reads
 * at CPU address 0x02000000 + off - 0x4000 through the SFC/cache. Data
 * outside the plain (unencrypted) window reads decrypted: see
 * fm1_flash.h fl_plain_window_init. */
       
/* SPDX-License-Identifier: GPL-3.0-only
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* FM1_INLINE: register helpers that must inline into their caller, so the
 * SFR access sequence (and its timing, in ISRs and IRQ-off sections) is the
 * one written at the call site; -Os would otherwise out-line a helper with
 * several callers. RAM-resident code (.ram_text) may only use these, never
 * a called helper (build.py checks .ram_text for calls). */
       
static inline const uint8_t *fm1_xip_ptr(uint32_t off) { (void)off; return armada_zero_page; }
typedef struct {
    uint32_t magic;
    uint16_t version;
    uint8_t nz, rsv;
    char name[8];
    uint32_t data_len, crc, rsv2[2];
    smp_zone_t zone[16];
} smp_user_hdr_t; /* 32 + 16 x 28 = 480 B, data at +512 */
/* A slot may hold a wavetable instead (WAVETABLE USR1..USR3, eng_wt.c): a 32-byte FWT1 header and int16
 * PCM frames at +512, frame-major, each frame the base (2^base_log2 samples) then its mip levels down to
 * 2^mip_last_log2. sizes/validity are derived from the header, so the editor and the engine share them. */
typedef struct {
    uint32_t magic;
    uint16_t version, frames;
    uint8_t base_log2, mip_last_log2, rsv[2];
    char name[8];
    uint32_t data_len, crc, rsv2;
} smp_wt_hdr_t; /* 32 B, data at +512 */
_Static_assert(sizeof(smp_wt_hdr_t) == 32u, "user wavetable header layout");
static uint32_t smp_wt_stride(const smp_wt_hdr_t *h)
{
    return (1u << (h->base_log2 + 1u)) - (1u << h->mip_last_log2);
}
static int smp_wt_ok(const smp_wt_hdr_t *h)
{
    uint32_t stride;
    if (h->magic != 0x31545746u || h->version != 1u || !h->frames || h->frames > 64u ||
        h->base_log2 < 4u || h->base_log2 > 12u || h->mip_last_log2 >= h->base_log2)
        return 0;
    stride = smp_wt_stride(h);
    return h->data_len == (uint32_t)h->frames * stride * 2u &&
           h->data_len <= 0x14000u - 512u;
}
