    int16_t *target[4u];
    const param_desc_t *desc[4u];
    uint32_t k, j;
    mw->on = 0;
    PKV(9)[((uint32_t)((t) - PKV(2)) % 4)] = 0; /* without a slot the render reads the real knobs */
    PKV(53)[((uint32_t)((t) - PKV(2)) % 4)] = 0;
    for (k = 0; k < 4u; k++)
        if (p[P_M1SRC + 3u * k] && p[P_M1DST + 3u * k] && p[P_M1AMT + 3u * k])
            break;
