static void pfx_end(void)
{
    uint32_t k;
    for (k = 0; k < 4; k++)
        if (PKV(2)[k].pfx & PFX_DEC) {
            int drum = PKV(2)[k].engine == 10u;
            PKV(2)[k].p[drum ? P_E3 : P_DEC] = PKV(137)[k][0];
            PKV(2)[k].p[drum ? P_E3 : P_REL] = PKV(137)[k][1];
            if (!drum)
                PKV(2)[k].p[P_SUS] = PKV(137)[k][3];
        }
    for (k = 0; k < 4; k++)
        if ((PKV(2)[k].pfx & PFX_ATK) && PKV(2)[k].engine != 10u)
            PKV(2)[k].p[P_ATK] = PKV(137)[k][2];
}
