/* copy the context state the stage st runs (FILTER's COMB, PHASR's pair; the rest has none) */
static void ins_ctx_stage(ins_ctx_t *d, const ins_ctx_t *src, uint32_t st)
{
    if (st == INS_FILTER)
        memcpy(d->comb, src->comb, sizeof d->comb);
    else if (st == INS_PHASR) {
        memcpy(d->px, src->px, sizeof d->px);
        memcpy(d->py, src->py, sizeof d->py);
    }
}
static void ins_master_reset(uint32_t st)
{
    if (st >= INS_N)
        return;
    memset(&PKV(177)[0][st], 0, sizeof PKV(177)[0][st]);
    memset(&PKV(177)[1][st], 0, sizeof PKV(177)[1][st]);
    memset(PKV(178)[0], 0, sizeof PKV(178)[0]);
    memset(PKV(178)[1], 0, sizeof PKV(178)[1]);
    if (st == INS_DIST)
        memset(&PKV(165), 0, sizeof PKV(165));
    if (st == INS_FILTER) {
        memset(PKV(163)[4].comb, 0, sizeof PKV(163)[0].comb);
        memset(PKV(163)[4 + 1].comb, 0, sizeof PKV(163)[0].comb);
    } else if (st == INS_PHASR) {
        memset(PKV(163)[4].px, 0, sizeof PKV(163)[0].px);
        memset(PKV(163)[4].py, 0, sizeof PKV(163)[0].py);
        memset(PKV(163)[4 + 1].px, 0, sizeof PKV(163)[0].px);
        memset(PKV(163)[4 + 1].py, 0, sizeof PKV(163)[0].py);
    }
}
/* route in or out of MASTER: its private state starts from silence (the shared buses' state is exclusive) */
static void fx_master_reset_stage(uint32_t st)
{
    if (st < INS_N) {
        ins_master_reset(st);
    } else if (st == INS_DLY) {
        memset(PKV(72), 0, sizeof PKV(72));
        memset(&PKV(73), 0, sizeof PKV(73));
        PKV(148) = 0;
        PKV(149) = 0;
    } else if (st == INS_REV) {
        PKV(75) = &PKV(74)[0];
        rev_clear();
        PKV(75)->rtype = (uint8_t)rev_rtype();
        PKV(75)->hl.side = 0;
    } else if (st == INS_SLCR) {
        slicer_master_reset();
    }
}
/* SEND bus knobs live in fx_bus_trk.p (core.h); packed into reclaimed project bytes. MIX stays per-track. */
static uint32_t ins_bus_tr(uint32_t st)
{
    uint32_t k;
    for (k = 0; k < 4; k++)
        if (ins_is_send(&PKV(2)[k], st))
            return k;
    return 0;
}
static void fx_bus_init(void)
{
    uint32_t i;
    for (i = 0; i < P_COUNT; i++)
        PKV(7).p[i] = TP[i].def;
}
static void fx_bus_from_wire(const uint8_t w[19u])
{
    uint32_t i;
    fx_bus_init();
    for (i = 0; i < 19u; i++)
        PKV(7).p[FX_BUS_PID[i]] = (int16_t)w[i];
}
static void fx_bus_to_wire(uint8_t w[19u])
{
    uint32_t i;
    for (i = 0; i < 19u; i++) {
        int32_t v = PKV(7).p[FX_BUS_PID[i]];
        w[i] = (uint8_t)(v < 0 ? 0 : v > 127 ? 127 : v);
    }
}
static void fx_bus_wire_def(uint8_t w[19u])
{
    fx_bus_init();
    fx_bus_to_wire(w);
}
static const track_t *ins_param_src(const track_t *t, uint32_t st)
{
    return st < INS_N && ins_is_send(t, st) ? bus_knobs_track(t) : t;
}
