            mix_part(&PKV(2)[k], n, &PKV(194));
            for (i = 0; i < n; i++) {
                sm->l[i] += PKV(194).l[i];
                sm->r[i] += PKV(194).r[i];
                sm->d[i] += PKV(194).d[i];
                sm->rv[i] += PKV(194).rv[i];
            }
            PKV(195) |= 1u << k; /* this part's sums are whole in mx[1] */
