    fm1_delay_ms(25);
    fm1_usb_attach(PKV(196));
    sie_wr(S_POWER, 0x60);
    sie_wr(S_INTRUSBE, 0x07u); /* suspend, resume, reset (polled) */
    sie_wr(S_INTRTX1E, 0x01u);
    sie_wr(S_INTRTX2E, 0);
    sie_wr(S_INTRRX1E, 0);
    sie_wr(S_INTRRX2E, 0);
    fm1_usb_ep_enable(0x1Fu);
