static uint32_t scale_mask(const track_t *t)
{
    return SCALE_MASK[clamp(t->p[P_SCALE], 0, sizeof SCALE_MASK / sizeof SCALE_MASK[0] - 1)];
}
/* note n moved down onto the track's scale (ROOT, SCALE): MAP ALL / SEQ sequenced notes */
static int32_t scale_snap(const track_t *t, int32_t n)
{
    uint32_t mask = scale_mask(t), guard = 12;
    while (guard-- && !((mask >> (uint32_t)((n - t->p[P_ROOT] + 120) % 12)) & 1u))
        n--;
    return n;
}
/* nearest in-scale pitch to n (tie: lower). MAP KBD's black keys */
static int32_t scale_nearest(const track_t *t, int32_t n)
{
    int32_t down = scale_snap(t, n), up = n;
    uint32_t mask = scale_mask(t), guard = 12;
    while (guard-- && !((mask >> (uint32_t)((up - t->p[P_ROOT] + 120) % 12)) & 1u))
        up++;
    return n - down <= up - n ? down : up;
}
/* (QN_*: core.h) MAP = ALL (stored QN_CURR) quantises exactly like CURR (stored QN_ALL) */
static inline uint32_t qn_mode(const track_t *t)
{
    return t->p[P_QUANT] == QN_CURR ? QN_ALL : (uint32_t)t->p[P_QUANT];
}
/* the engine's own key map (DRUM's GM map, slices) for key k, -1 none */
static int32_t kb_engine(const track_t *t, uint32_t k)
{
    const engine_t *e = ENGINES[eng_idx(t->eng_req)]; /* (the engine it switches to) */
    return e->keys ? e->keys(t, k) : -1;
}
/* key k's note with the octave buttons at oct: MAP, ROOT, SCALE, TRN. The keys (kb_map) and the arp's latched
 * keys (arp_list, #191: as the keys play now, the octave they were pressed in) */
static uint32_t kb_pitch(const track_t *t, uint32_t k, int32_t oct)
{
    static const int8_t DEGREE[12] = {0, -1, 1, -1, 2, 3, -1, 4, -1, 5, -1, 6};
    int32_t n = 53 + (int32_t)k;
    if (qn_mode(t) == QN_KBD || qn_mode(t) == QN_ALL) { /* KBD / CURR / ALL: white walk; black -> nearest */
        uint32_t mask = scale_mask(t), i;
        int32_t count = 0, degree = DEGREE[n % 12], wo;
        if (degree < 0) /* black: chromatic pitch, closest in-scale (dup OK) */
            return (uint32_t)clamp(scale_nearest(t, n + 12 * oct + t->p[P_TRANS]), 0, 127);
        /* C4 is the root. Walk scale degrees on successive white keys, including
         * below C4; scales with 5, 6 or 8 notes still have no duplicated degrees. */
        degree += (n / 12 - 5) * 7;
        for (i = 0; i < 12u; i++)
            count += (mask >> i) & 1u;
        wo = degree / count;
        degree %= count;
        if (degree < 0) {
            degree += count;
            wo--;
        }
        for (i = 0; i < 12u; i++)
            if ((mask >> i) & 1u) {
                if (!degree)
                    break;
                degree--;
            }
        n = 60 + t->p[P_ROOT] + 12 * wo + (int32_t)i;
        return (uint32_t)clamp(n + 12 * oct + t->p[P_TRANS], 0, 127);
    }
    /* OFF and SEQ: chromatic piano (ALL / SEQ remap sequenced notes in seq_step) */
    return (uint32_t)clamp(n + 12 * oct + t->p[P_TRANS], 0, 127);
}
static uint32_t kb_map(const track_t *t, uint32_t k)
{
    int32_t n = kb_engine(t, k);
    return n >= 0 ? (uint32_t)n : kb_pitch(t, k, PKV(6).octave);
}
/* SPDX-License-Identifier: GPL-3.0-only
 * Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments */
/* Chord keys (SCL > CHORD: P_CHRD, P_VOIC): one key, MIDI note or arp input plays a chord. Included by seq.c
 * after kb_map; runs in the audio ISR with the rest of the note input.
 *   CHRD OFF; DIA3 / DIA7: the triad / seventh of the track's scale (ROOT, SCALE) built on the key, every tone
 *        in key (a key outside the scale takes the scale note below it); MAJ MIN DOM7 MAJ7 MIN7 SUS4 POW: that
 *        shape on the key, whatever the scale.
 *   VOIC CLOSE (root position); OPEN (the second tone an octave up: 1-5-3); INV1 / INV2 (the lowest tone, then
 *        the next, an octave up); +OCT (the root an octave down added; a seventh drops its fifth). At most
 *        CHORD_MAX notes, notes outside 0..127 left out.
 * The key is mapped first (kb_map: MAP KBD / ALL, TRN, the octave), the chord is built on the note it gives.
 * MONO / LEGATO / UNISON parts play the chord's root only; a kit (the DRUM engine, slices: an
 * engine that maps the keys itself) ignores CHRD. Every source keeps the notes it started (kb_chord for a
 * key, mchord for a MIDI note) and its release ends exactly those, so CHRD / VOIC changed while it is held
 * leave nothing hanging. A note several sources hold sounds once and ends with the last of them. */
/* Append modes: these values are stored in songs, presets and editor files. */
enum { CH_OFF, CH_DIA3, CH_DIA7, CH_MAJ, CH_MIN, CH_DOM7, CH_MAJ7, CH_MIN7, CH_SUS4, CH_POW, CH_AUTO, CH_MELODY };
enum { VC_CLOSE, VC_OPEN, VC_INV1, VC_INV2, VC_BASS };
