/* MELO harmony: the mapped key is the melody, always on top. Chord selection is a pure function of
 * scale, root and melody pitch class; accompaniment tracks, earlier presses and UI previews cannot
 * change it. Included by chord.c after chord_kit. Fixed searches, no allocation or history. */
typedef struct { uint8_t pitch[3], cost; const char *name; } chord_melody_shape_t;
static const chord_melody_shape_t CH_MELODY_SHAPE[] = {
    {{0,4,7}, 0, ""}, {{0,3,7}, 0, "m"},
    {{0,3,6}, 24, "dim"}, {{0,4,8}, 16, "aug"},
    {{0,5,7}, 18, "sus4"}, {{0,2,7}, 18, "sus2"},
};
static uint32_t chord_melody_rotate(uint32_t bits, int32_t semitones)
{
    uint32_t n = (uint32_t)((semitones % 12 + 12) % 12);
    bits &= 0xFFFu;
    return ((bits << n) | (bits >> (12u - n))) & 0xFFFu;
}
static int32_t chord_melody_mapped(const track_t *t, uint32_t input)
{
    uint32_t allowed = chord_melody_rotate(scale_mask(t), t->p[P_ROOT]);
    int32_t note = (int32_t)input;
    while (note >= 0 && !(allowed & (1u << (uint32_t)(note % 12)))) note--;
    if (note < 0) { note = 0; while (!(allowed & (1u << (uint32_t)(note % 12)))) note++; }
    return note;
}
static int32_t chord_melody_below(int32_t melody, uint32_t pitch_class)
{
    return melody - (melody - (int32_t)pitch_class + 12) % 12;
}
static uint32_t chord_melody_make(const track_t *t, uint32_t input, uint8_t *out, int32_t *rp, uint16_t *maskp)
{
    int32_t tonic = t->p[P_ROOT], melody = chord_melody_mapped(t, input);
    uint32_t allowed = chord_melody_rotate(scale_mask(t), tonic), pc = (uint32_t)melody % 12u;
    *rp = melody; *maskp = 1;
    if (trk_vmode(t) != V_POLY) { out[0] = (uint8_t)melody; return 1; }
    uint32_t root = pc, chosen = 0xFFFFu, mask = 0;
    int32_t best = 0x7FFFFFFF;
    /* Visit roots relative to the tonic so equal scores transpose consistently. */
    for (uint32_t degree = 0; degree < 12u; degree++) {
        uint32_t r = (uint32_t)((tonic + (int32_t)degree + 120) % 12);
        if (!(allowed & (1u << r))) continue;
        /* Tonic harmony anchors its own tones. The fourth/fifth roots are next;
         * a melody-root triad wins ordinary ties. Colour chords are fallbacks,
         * never selected just to chase passing notes in another track. */
        int32_t root_cost = !degree ? 0 : degree == 7u ? 8 : degree == 5u ? 10 : 14;
        for (uint32_t s = 0; s < (sizeof(CH_MELODY_SHAPE) / sizeof((CH_MELODY_SHAPE)[0])); s++) {
            uint32_t shape = 0;
            for (uint32_t j = 0; j < 3u; j++) shape |= 1u << CH_MELODY_SHAPE[s].pitch[j];
            uint32_t pcs = chord_melody_rotate(shape, (int32_t)r);
            if ((pcs & ~allowed) || !(pcs & (1u << pc))) continue;
            int32_t score = root_cost + CH_MELODY_SHAPE[s].cost - (r == pc ? 6 : 0);
            if (score < best) { best = score; root = r; chosen = s; mask = shape; }
        }
    }
    int32_t notes[4]; uint32_t n = 0;
    if (chosen < (sizeof(CH_MELODY_SHAPE) / sizeof((CH_MELODY_SHAPE)[0]))) {
        for (uint32_t i = 0; i < 3u; i++)
            notes[n++] = chord_melody_below(melody, (root + CH_MELODY_SHAPE[chosen].pitch[i]) % 12u);
    } else {
        /* Keep the melody and two separated lower degrees if no named triad
         * contains it. The display calls this a set rather than inventing a name. */
        notes[n++] = melody;
        int32_t note = melody; uint32_t degree = 0;
        while (n < 3u) {
            note--;
            if (allowed & (1u << (uint32_t)((note + 120) % 12))) {
                degree++;
                if (!(degree & 1u)) notes[n++] = note;
            }
        }
        root = (uint32_t)((notes[2] + 120) % 12);
        for (uint32_t i = 0; i < n; i++) mask |= 1u << (uint32_t)((notes[i] - (int32_t)root + 120) % 12);
    }
    for (uint32_t i = 1; i < n; i++)
        for (uint32_t j = i; j && notes[j] < notes[j-1u]; j--) {
            int32_t x = notes[j]; notes[j] = notes[j-1u]; notes[j-1u] = x;
        }
    /* Every voicing keeps the melody fixed. Only the lower voices move. */
    uint32_t voicing = chord_voic(t);
    if (voicing == VC_OPEN) notes[0] -= 12;
    else if (voicing == VC_BASS || voicing == VC_INV1 || voicing == VC_INV2) {
        uint32_t bass = root;
        if (voicing != VC_BASS && chosen < (sizeof(CH_MELODY_SHAPE) / sizeof((CH_MELODY_SHAPE)[0])))
            bass = (root + CH_MELODY_SHAPE[chosen].pitch[voicing == VC_INV1 ? 1u : 2u]) % 12u;
        uint32_t at = n;
        if (voicing != VC_BASS)
            for (uint32_t i = 0; i + 1u < n; i++)
                if ((uint32_t)((notes[i] + 120) % 12) == bass) { at = i; break; }
        int32_t low = chord_melody_below(melody, bass);
        if (at == n) do { low -= 12; } while (low >= notes[0]);
        else while (low > notes[0]) low -= 12;
        notes[at] = low;
        if (at == n) n++;
    }
    /* At MIDI's lower endpoint omit unavailable accompaniment, never move the
     * melody up an octave to make room for a full chord. */
    uint32_t count = 0;
    for (uint32_t i = 0; i < n; i++) if (notes[i] >= 0) out[count++] = (uint8_t)notes[i];
    for (uint32_t i = 1; i < count; i++)
        for (uint32_t j = i; j && out[j] < out[j-1u]; j--) {
            uint8_t x = out[j]; out[j] = out[j-1u]; out[j-1u] = x;
        }
    *rp = (int32_t)root; *maskp = (uint16_t)mask;
    if (count == 1u) { *rp = melody; *maskp = 1; }
    return count;
}
static void chord_melody_name(char *b, uint32_t root, uint32_t mask)
{
    const char *name = mask == 1u ? "" : " set";
    for (uint32_t i = 0; i < (sizeof(CH_MELODY_SHAPE) / sizeof((CH_MELODY_SHAPE)[0])); i++) {
        uint32_t shape = 0;
        for (uint32_t j = 0; j < 3u; j++) shape |= 1u << CH_MELODY_SHAPE[i].pitch[j];
        if (shape == mask) { name = CH_MELODY_SHAPE[i].name; break; }
    }
    str_cpy(b, N_NOTE[root % 12u], 12);
    str_cpy(b + str_len(b), name, 12 - str_len(b));
}
/* the tones of the chord (semitones above *root, ascending, iv[0] = 0) -> their number; DIA may move *root
 * down onto the scale */
static uint32_t chord_tones(const track_t *t, uint32_t mode, int32_t *root, int32_t *iv)
{
    uint32_t n = 0, i;
    if (mode >= CH_MAJ) {
        for (i = 0; i < 4u && CHORD_SHAPE[mode - CH_MAJ][i] >= 0; i++)
            iv[n++] = CHORD_SHAPE[mode - CH_MAJ][i];
        return n;
    }
    {
        uint32_t mask = scale_mask(t), deg[12], c = 0, at = 0, guard = 12;
        int32_t r = t->p[P_ROOT];
        while (guard-- && !((mask >> (uint32_t)((*root - r + 120) % 12)) & 1u))
            (*root)--; /* outside the scale: the scale note below */
        for (i = 0; i < 12u; i++)
            if ((mask >> i) & 1u) {
                if (i == (uint32_t)((*root - r + 120) % 12))
                    at = c;
                deg[c++] = i;
            }
        for (i = 0; i < (mode == CH_DIA7 ? 4u : 3u); i++) { /* every other note of the scale */
            uint32_t k = at + 2u * i;
            iv[n++] = (int32_t)deg[k % c] + 12 * (int32_t)(k / c) - (int32_t)deg[at];
        }
        return n;
    }
}
/* the chord on note `root` as track t plays it now -> out (ascending), the number of notes (1..CHORD_MAX);
 * *rp its root, *maskp its tones above the root (bit i: i semitones; 0 = no chord). The root alone when CHRD
 * is OFF, on a kit, or for MONO / LEGATO / UNISON (their chord's root) */
static uint32_t chord_make(const track_t *t, uint32_t root, uint8_t *out, int32_t *rp, uint16_t *maskp)
{
    int32_t iv[4u + 1u], r = (int32_t)root, x;
    uint32_t mode = chord_mode(t), n, i, j, m = 0;
    uint16_t mask = 0;
    *rp = r;
    *maskp = 0;
    if (!mode || mode > CH_MELODY || chord_kit(t)) {
        out[0] = (uint8_t)root;
        return 1;
    }
    if (mode == CH_AUTO)
        return chord_auto_make(t, root, out, rp, maskp);
    if (mode == CH_MELODY)
        return chord_melody_make(t, root, out, rp, maskp);
    n = chord_tones(t, mode, &r, iv);
    for (i = 0; i < n; i++)
        mask |= (uint16_t)(1u << (iv[i] % 12));
    *rp = r;
    *maskp = mask;
    if (trk_vmode(t) != V_POLY) { /* one voice: the root */
        out[0] = (uint8_t)clamp(r, 0, 127);
        return 1;
    }
    switch (chord_voic(t)) {
    case VC_OPEN: /* 1-5-3(-7): the second tone an octave up */
        if (n >= 3u)
            iv[1] += 12;
        break;
    case VC_INV2:
    case VC_INV1:
        for (j = 0; j < (chord_voic(t) == VC_INV2 ? 2u : 1u); j++) { /* the lowest tone an octave up */
            x = iv[0] + 12;
            for (i = 1; i < n; i++)
                iv[i - 1u] = iv[i];
            iv[n - 1u] = x;
        }
        break;
    case VC_BASS: /* the root an octave down; a seventh drops its fifth */
        if (n == 4u) {
            iv[2] = iv[3];
            n--;
        }
        for (i = n; i > 0; i--)
            iv[i] = iv[i - 1u];
        iv[0] = -12;
        n++;
        break;
    default:
        break;
    }
    for (i = 1; i < n; i++) /* ascending */
        for (j = i; j > 0 && iv[j - 1u] > iv[j]; j--) {
            x = iv[j];
            iv[j] = iv[j - 1u];
            iv[j - 1u] = x;
        }
    for (i = 0; i < n && m < 4u; i++) { /* inside 0..127, each note once */
        x = r + iv[i];
        if (x < 0 || x > 127 || (m && out[m - 1u] == (uint8_t)x))
            continue;
        out[m++] = (uint8_t)x;
    }
    if (!m) {
        out[0] = (uint8_t)clamp(r, 0, 127);
        return 1;
    }
    return m;
}
/* chord_make for a note played now: a chord is kept in chord_last (the CHORD page shows it) */
static uint32_t chord_build(track_t *t, uint32_t root, uint8_t *out)
{
    int32_t r;
    uint16_t mask;
    uint32_t m = chord_make(t, root, out, &r, &mask), i, k = trk_index(t);
    if (chord_mode(t) == CH_AUTO && !chord_kit(t) && trk_vmode(t) == V_POLY)
        chord_auto_remember(t, r, mask, out, m);
    if (m > 1u || chord_mode(t) == CH_MELODY) {
        PKV(235)[k].root = (uint8_t)clamp(r, 0, 127);
        PKV(235)[k].mask = mask;
        PKV(235)[k].n = (uint8_t)m;
        for (i = 0; i < 4u; i++)
            PKV(235)[k].note[i] = i < m ? out[i] : 0u;
    }
    return m;
}
/* a chord's name from its root and tones (bit i: i semitones above the root): "C", "Cm7", "F#m7b5", "Gsus4",
 * "A5" -> b (12 bytes) */
static void chord_name(char *b, uint32_t root, uint32_t mask)
{
    uint32_t mi = (mask >> 3) & 1u, ma = (mask >> 4) & 1u, b5 = (mask >> 6) & 1u, p5 = (mask >> 7) & 1u;
    uint32_t s5 = (mask >> 8) & 1u, d7 = (mask >> 9) & 1u, m7 = (mask >> 10) & 1u, M7 = (mask >> 11) & 1u;
    const char *q, *x = "";
    str_cpy(b, N_NOTE[root % 12u], 12);
    if (mi && !ma && b5 && !p5)
        q = d7 ? "dim7" : m7 ? "m7b5" : "dim";
    else if (ma && !mi && s5 && !p5)
        q = m7 ? "+7" : M7 ? "+M7" : "aug";
    else if (ma && !mi)
        q = m7 ? "7" : M7 ? "maj7" : d7 ? "6" : "";
    else if (mi)
        q = m7 ? "m7" : M7 ? "mM7" : d7 ? "m6" : "m";
    else if ((mask >> 5) & 1u) { /* no third: suspended */
        q = m7 ? "7" : "";
        x = "sus4";
    } else if ((mask >> 2) & 1u) {
        q = m7 ? "7" : "";
        x = "sus2";
    } else
        q = "5";
    str_cpy(b + str_len(b), q, 12 - str_len(b));
    str_cpy(b + str_len(b), x, 12 - str_len(b));
}
/* ------------------------------------------------------------- STRUM --- */
/* A division is the whole first-to-last sweep: onset k = (beat / DEN[rate]) * k / (n - 1), kept as a beat
 * fraction, so a tempo change mid-sweep keeps the proportions. Rate and direction freeze at the press. */
static const uint8_t STRUM_DEN[] = {1, 2, 4, 8, 16, 32, 6, 12}; /* OFF, 1/8 .. 1/128, 16T, 32T */
/* 1 = started (sound the first tone, then tick the rest), 0 = play the chord at once */
static int chord_strum_begin(track_t *t, uint8_t *notes, uint32_t n, chord_strum_t *s, uint32_t vel)
{
    uint32_t rate = sweep_rate(t), stroke = sweep_stroke(t), i;
    memset(s, 0, sizeof *s);
    if (!rate || rate >= (sizeof(STRUM_DEN) / sizeof((STRUM_DEN)[0])) || n < 2u || t->p[P_AMODE])
        return 0;
    if (stroke == 2u)
        stroke = (uint32_t)(PKV(234)[trk_index(t)]++ & 1u);
    if (stroke == 1u) /* UP: the same sweep, top to bottom */
        for (i = 0; i < n / 2u; i++) {
            uint8_t x = notes[i];
            notes[i] = notes[n - 1u - i];
            notes[n - 1u - i] = x;
        }
    if (!stroke && chord_mode(t) == CH_MELODY) {
        /* MELO: the melody sounds on the press; DOWN orders the accompaniment below it. */
        uint8_t melody = notes[n - 1u];
        for (i = n - 1u; i; i--) notes[i] = notes[i - 1u];
        notes[0] = melody;
    }
    s->total = (uint8_t)n;
    s->rate = (uint8_t)rate;
    s->vel = (uint8_t)vel;
    s->beat = beat_samples() ? beat_samples() : 1u;
    return 1;
}
/* samples still due before `started` more tones (0: fire one), after `elapsed` samples */
static uint32_t chord_strum_due(chord_strum_t *s, uint32_t started, uint32_t elapsed)
{
    uint32_t beat = beat_samples() ? beat_samples() : 1u;
    if (s->beat != beat) { /* tempo moved: keep the beat fraction */
        s->pos = (uint32_t)(((uint64_t)s->pos * beat + s->beat / 2u) / s->beat);
        s->beat = beat;
    }
    s->pos += elapsed;
    {
        uint32_t target = (beat / STRUM_DEN[s->rate]) * started / (s->total - 1u);
        return s->pos < target ? target - s->pos : 0u;
    }
}
/* a strummed tone into the note input, tagged so the free take can put it back on the take's tempo */
static void chord_strum_input(track_t *t, uint32_t note, uint32_t vel, const chord_strum_t *s, uint32_t i)
{
    PKV(230).on = 1;
    PKV(230).rate = s->rate;
    PKV(230).index = (uint8_t)i;
    PKV(230).total = s->total;
    input_on(t, note, vel);
    PKV(230).on = 0;
}
static void key_chord_tone(uint32_t k, track_t *t)
{
    uint32_t i = PKV(228)[k], note, mc = trk_midi_ch(trk_index(t));
    if (i >= 4u)
        return;
    note = PKV(227)[k][i];
    if (midi_local_held(t, note)) { /* (checked before counting it as started) */
        PKV(228)[k] = (uint8_t)(i + 1u);
        return;
    }
    PKV(228)[k] = (uint8_t)(i + 1u);
    chord_strum_input(t, note, 100, &PKV(229)[k], i);
    midi_out_event(0x09u | (0x90u | mc) << 8 | note << 16 | 100u << 24);
}
static void midi_chord_tone(mchord_t *m)
{
    track_t *t = &PKV(2)[m->id - 1u];
    uint32_t i = m->n, note;
    if (i >= 4u)
        return;
    note = m->note[i];
    if (!midi_note_held(t, note) && !midi_local_held(t, note)) /* (self excluded: n still i) */
        chord_strum_input(t, note, m->strum.vel, &m->strum, i);
    m->n = (uint8_t)(i + 1u);
}
/* one block: fire the strings whose onset is due */
static void chord_strum_tick(uint32_t n)
{
    uint32_t k;
    for (k = 0; k < 27u && PKV(232); k++)
        if (PKV(232) & (1u << k)) {
            chord_strum_t *s = &PKV(229)[k];
            chord_strum_due(s, PKV(228)[k], n);
            while (PKV(228)[k] < s->total && !chord_strum_due(s, PKV(228)[k], 0))
                key_chord_tone(k, &PKV(2)[PKV(218)[k]]);
            if (PKV(228)[k] >= s->total)
                PKV(232) &= ~(1u << k);
        }
    for (k = 0; k < 24u && PKV(233); k++)
        if (PKV(233) & (1u << k)) {
            mchord_t *m = &PKV(231)[k];
            chord_strum_due(&m->strum, m->n, n);
            while (m->n < m->strum.total && !chord_strum_due(&m->strum, m->n, 0))
                midi_chord_tone(m);
            if (m->n >= m->strum.total)
                PKV(233) &= ~(1u << k);
        }
}
/* the MIDI note (ch, src) of track id - 1 that plays a chord, 0 = none */
static mchord_t *mchord_of(uint32_t ch, uint32_t src, uint32_t id)
{
    uint32_t i;
    for (i = 0; i < 24u; i++)
        if (PKV(231)[i].id == id && PKV(231)[i].ch == ch && PKV(231)[i].src == src)
            return &PKV(231)[i];
    return 0;
}
/* a MIDI-held chord of track id - 1 sounds note */
static int mchord_held(uint32_t id, uint32_t note)
{
    uint32_t i, j;
    for (i = 0; i < 24u; i++)
        if (PKV(231)[i].id == id)
            for (j = 0; j < PKV(231)[i].n; j++)
                if (PKV(231)[i].note[j] == note)
                    return 1;
    return 0;
}
static void mchord_forget(uint32_t track) /* panic: the track's MIDI chords are gone */
{
    chord_auto_forget(track);
    uint32_t i;
    for (i = 0; i < 27u; i++)
        if (PKV(218)[i] == track)
            PKV(232) &= ~(1u << i);
    for (i = 0; i < 24u; i++)
        if (PKV(231)[i].id == track + 1u) {
            PKV(231)[i].id = 0;
            PKV(233) &= ~(1u << i);
        }
}
/* ------------------------------------------------------------- arp --- */
static void arp_add(track_t *t, uint32_t note)
{
    uint32_t i, k = PKV(219) - 1u;
    if (t->p[P_AHOLD] && t->arp_phys == 0u)
        t->nheld = 0; /* new chord replaces the latched one */
    t->arp_phys++; /* every key-down: arp_remove counts every key-up */
    for (i = 0; i < t->nheld; i++)
        if (t->held[i] == note)
            return; /* repeated note-on: not a new note */
    if (t->nheld < 16u) {
        /* #191: a key the track's scale keyboard maps (not the DRUM grid, not an engine's own map) is kept as that
         * key, so TRN, ROOT, SCALE and QNT reach the notes the arp holds (arp_list); the octave stays the one it was
         * pressed in. Anything else (MIDI IN) plays as it came, as before */
        uint8_t *hk = PKV(220)[trk_index(t)];
        hk[t->nheld] = PKV(219) && PKV(6).grid != 1u && kb_engine(t, k) < 0
                           ? (uint8_t)(PKV(219) | (uint32_t)(PKV(6).octave + 3) << 5) : 0u;
        PKV(221)[trk_index(t)][t->nheld] = (int8_t)(hk[t->nheld] ? (int32_t)note - PKV(217)[k] : 0);
        t->held[t->nheld++] = (uint8_t)note;
    }
    if (t->nheld == 1u) {
        t->arp_pos = 0xFFFFFFF; /* fire on this block */
        t->arp_idx = 0xFFFFFFFFu;
    }
}
static void arp_remove(track_t *t, uint32_t note)
{
    uint32_t i, k = 0;
    uint8_t *hk = PKV(220)[trk_index(t)];
    int8_t *dt = PKV(221)[trk_index(t)];
    if (t->arp_phys)
        t->arp_phys--;
    if (t->p[P_AHOLD])
        return;
    for (i = 0; i < t->nheld; i++)
        if (t->held[i] != note) {
            hk[k] = hk[i];
            dt[k] = dt[i];
            t->held[k++] = t->held[i];
        }
    t->nheld = (uint8_t)k;
}
static void rec_note(track_t *t, uint32_t note, uint32_t vel);
static void rec_release(track_t *t, uint32_t note);
static void seq_start(void);
static int rec_on(const track_t *t) { return ((PKV(6).rec >> trk_index(t)) & 1u) && PKV(6).playing && !PKV(214).running; }
static int pfx_rec_ok(void) { return PKV(6).rec && PKV(6).playing && !PKV(214).running; } /* (pfx.c: punch-in lane) */
static void ft_note_on(uint32_t note, uint32_t vel);
static void ft_note_off(uint32_t note);
static int ft_rec_track(const track_t *t); /* a free take runs on t */
static void arm_start(track_t *t);
/* an ARP note goes into the take that owns the track: a live REC, or the free take (SLOOP).
 * Its first note starts the free take, so the take's step 0 is the arp's first step */
static void arp_take_on(track_t *t, uint32_t note, uint32_t vel)
{
    arm_start(t);
    if (rec_on(t))
        rec_note(t, note, vel);
    else if (ft_rec_track(t))
        ft_note_on(note, vel);
}
static void arp_take_off(track_t *t, uint32_t note)
{
    if (rec_on(t))
        rec_release(t, note);
    else if (ft_rec_track(t))
        ft_note_off(note);
}
